import json
from typing import Optional

class Tool:
    name: str
    description: str
    func: Optional[callable] = None

class ReActAgent:
    def __init__(self, tools=None):
        self.tools = tools or []
        self.memory = []

    def think(self, query: str) -> str:
        '''Reason about the query and decide on action.'''
        if any(op in query for op in ['+', '-', '*', '/']):
            return f'ACTION: calculate({query})'
        return f'ANSWER: Based on knowledge, {query}'

    def act(self, action: str) -> str:
        '''Execute the action and return result.'''
        if action.startswith('calculate:'):
            expr = action[len('calculate:'):]
            try:
                result = eval(expr)
                return f'OBSERVATION: {result}'
            except:
                return f'OBSERVATION: Error calculating {expr}'
        return f'OBSERVATION: Not implemented'

    def run(self, query: str) -> str:
        '''Run the ReAct loop.'''
        steps = 0
        while steps < 10:
            thought = self.think(query)
            if thought.startswith('ANSWER:'):
                return thought[9:].strip()
            action = self.act(thought)
            self.memory.append((thought, action))
            if 'OBSERVATION:' in action:
                query = action
            steps += 1
        return 'Max steps reached'

